// Independent, scoped review application. No published city, account or analytics code is loaded.
const response=await fetch('./greater-taipei-data.json?rev=1');
if(!response.ok)throw Error('Preview data unavailable');
const data=await response.json();
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const palette={taipei:{accent:'#315c96',soft:'#e8f0fa',border:'#b7cce6'},newtaipei:{accent:'#8b692b',soft:'#f8f0d9',border:'#dbbd77'}};
const scene=new THREE.Scene();scene.background=new THREE.Color('#91c4df');scene.fog=new THREE.Fog('#9ec9da',1400,3200);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;
renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.info.autoReset=false;
$('#stage').append(renderer.domElement);
const camera=new THREE.PerspectiveCamera(40,innerWidth/innerHeight,.6,4000),controls=new OrbitControls(camera,renderer.domElement);
controls.enableDamping=true;controls.dampingFactor=.075;controls.minDistance=8;controls.maxDistance=1800;controls.maxPolarAngle=Math.PI*.48;controls.minPolarAngle=.14;
const hemi=new THREE.HemisphereLight('#d2ecff','#6c784b',1.65),sun=new THREE.DirectionalLight('#fff0cc',3.3);sun.position.set(-150,290,170);sun.target.position.set(-80,0,-12);sun.castShadow=true;sun.shadow.mapSize.set(4096,4096);
Object.assign(sun.shadow.camera,{left:-330,right:330,top:250,bottom:-250,near:1,far:1000});sun.shadow.normalBias=.05;sun.shadow.bias=-.0001;sun.shadow.radius=3;scene.add(hemi,sun,sun.target);
const pmrem=new THREE.PMREMGenerator(renderer),room=new RoomEnvironment(),environment=pmrem.fromScene(room,.04);scene.environment=environment.texture;room.dispose();pmrem.dispose();
const sky=new Sky();sky.scale.setScalar(2500);sky.material.uniforms.turbidity.value=2.6;sky.material.uniforms.rayleigh.value=1.05;sky.material.uniforms.sunPosition.value.copy(sun.position);installTaipeiSkyClouds(sky);sky.material.fragmentShader=sky.material.fragmentShader.replace('retColor=mix(retColor,citySkyTint,smoothstep(.025,.3,direction.y)*.45);','retColor=mix(retColor*.3,citySkyTint,.65);');scene.add(sky);
const ocean=new THREE.Mesh(new THREE.PlaneGeometry(6000,6000),new THREE.MeshStandardMaterial({color:'#309eb8',roughness:.42,metalness:.2,envMapIntensity:.3}));ocean.name='metropolitan-ocean';ocean.rotation.x=-Math.PI/2;ocean.position.y=-1.35;scene.add(ocean);
ocean.material.onBeforeCompile=s=>{s.vertexShader=s.vertexShader.replace('#include <common>','#include <common>\nvarying vec2 vMetroSea;').replace('#include <begin_vertex>','#include <begin_vertex>\nvMetroSea=position.xy;');s.fragmentShader=s.fragmentShader.replace('#include <common>','#include <common>\nvarying vec2 vMetroSea;').replace('#include <color_fragment>','#include <color_fragment>\nfloat ripples=sin(vMetroSea.x*.7+vMetroSea.y*.31+sin(vMetroSea.y*.18)*1.7)+sin(vMetroSea.x*.12-vMetroSea.y*.65)*.4; diffuseColor.rgb*=.97+ripples*.025;');};
const cities={};
$('#entry-note').textContent='建立臺北市的街區、湖岸與城市生活…';
await new Promise(r=>setTimeout(r,0));
cities.taipei=buildGreaterCity(renderer,scene,'taipei',{position:[0,0,0],scale:1});
$('#entry-note').textContent='連結新北市的生活街區與公共服務…';
await new Promise(r=>setTimeout(r,0));
cities.newtaipei=buildGreaterCity(renderer,scene,'newtaipei',{position:[-185,0,-24],scale:.92});
// A conceptual pedestrian connection joins the two physical city roots.
const linkA=cities.newtaipei.toWorld([79,.65,-41]),linkB=cities.taipei.toWorld([-58,.65,-38]);
const link=new THREE.Group();link.name='metropolitan-connection';link.position.copy(linkA).add(linkB).multiplyScalar(.5);link.rotation.y=Math.atan2(linkB.x-linkA.x,linkB.z-linkA.z);scene.add(link);
const length=linkA.distanceTo(linkB),deck=new THREE.Mesh(new THREE.BoxGeometry(3.5,.35,length),new THREE.MeshStandardMaterial({color:'#d8d2b7',roughness:.85}));deck.receiveShadow=true;deck.castShadow=true;link.add(deck);
for(const x of [-1.6,1.6]){const points=[];for(let i=0;i<=40;i++){const z=-length/2+i*length/40,y=.45+Math.sin(i/40*Math.PI)*7;points.push(new THREE.Vector3(x,y,z));if(i%4===0){const post=new THREE.Mesh(new THREE.BoxGeometry(.07,Math.max(.05,y),.07),new THREE.MeshStandardMaterial({color:'#c7d3c5'}));post.position.set(x,y/2,z);link.add(post);}}const arch=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),70,.12,7,false),new THREE.MeshStandardMaterial({color:'#e8e7ce'}));link.add(arch);}

const composer=new EffectComposer(renderer);if(renderer.capabilities.isWebGL2){composer.renderTarget1.samples=4;composer.renderTarget2.samples=4;}composer.addPass(new RenderPass(scene,camera));
const ao=new SSAOPass(scene,camera,innerWidth,innerHeight);ao.kernelRadius=.8;ao.minDistance=.0001;ao.maxDistance=.008;excludeSkyOverlaysFromAO(ao,scene);composer.addPass(ao);composer.addPass(new OutputPass());
const state={city:'taipei',view:'city',entered:false,selected:null,time:'day',night:false,motion:false,music:false,guide:null};
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let flight=null,orbitTimer=null,elapsed=0,statusTimer;
const current=()=>data.cities.find(c=>c.id===state.city),model=()=>cities[state.city];
function node(tag,text,className){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(className)el.className=className;return el;}
function stopOrbit(){clearTimeout(orbitTimer);controls.autoRotate=false;}
function status(text){$('#status').textContent=text;$('#status').hidden=false;clearTimeout(statusTimer);statusTimer=setTimeout(()=>$('#status').hidden=true,4200);}
function focus(position,target,instant=false){stopOrbit();if(instant||reduced.matches){flight=null;camera.position.copy(position);controls.target.copy(target);controls.update();}else flight={from:camera.position.clone(),to:position.clone(),start:controls.target.clone(),end:target.clone(),time:performance.now()};}
function cityView(id,instant=false){const city=cities[id],target=city.toWorld([-2,12,8]),offset=innerWidth<760?new THREE.Vector3(40,205,330):new THREE.Vector3(134,133,167);offset.multiplyScalar(city.root.scale.x);focus(target.clone().add(offset),target,instant);}
function setCity(id,{focusCamera=true,instant=false}={}){if(!cities[id])return false;stopGuide();state.city=id;state.view='city';state.selected=null;closePanel();closeMenu();for(const [key,value] of Object.entries(palette[id]))document.documentElement.style.setProperty('--'+key,value);all('[data-city]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.city===id)));rebuildPins();if(focusCamera)cityView(id,instant);return true;}
function home(instant=false){setCity('taipei',{instant});}
function panorama(instant=false){stopGuide();closePanel();closeMenu();state.view='panorama';state.selected=null;const target=new THREE.Vector3(-82,13,-8),offset=innerWidth<760?new THREE.Vector3(75,550,1100):new THREE.Vector3(245,285,435);focus(target.clone().add(offset),target,instant);if(!reduced.matches)orbitTimer=setTimeout(()=>{if(state.view==='panorama'){controls.autoRotate=true;controls.autoRotateSpeed=.15;}},5000);}
controls.addEventListener('start',()=>{flight=null;stopOrbit();stopGuide();});
controls.addEventListener('end',()=>{if(state.view==='panorama'||state.guide)return;const candidates=Object.values(cities).map(c=>({id:c.id,distance:controls.target.distanceTo(c.toWorld([0,0,0]))})).sort((a,b)=>a.distance-b.distance);if(candidates[0].id!==state.city&&candidates[0].distance<70)setCity(candidates[0].id,{focusCamera:false});});

const anchors={
 'tp-transport':[13,3,10],'tp-housing':[-21,20,-3],'tp-ai':[28,43,-31],'tp-childcare':[-9,12,-22],'tp-education':[-43,8,16],'tp-senior':[39,15,21.5],'tp-sports':[-43,4,29],'tp-youth':[-18,15,55],'tp-health':[-33,12,49],
 'nt-transport':[13,3,10],'nt-housing':[-21,20,-3],'nt-family':[-9,12,-22],'nt-elderly':[39,15,21.5],'nt-health':[33,12,48],'nt-education':[-43,8,16],'nt-industry':[28,43,-31],'nt-disaster':[28,4,21],'nt-community':[-18,15,55]
};
const recordAnchors={'tp-rec-transport':anchors['tp-transport'],'tp-rec-housing':anchors['tp-housing'],'tp-rec-welfare':anchors['tp-senior'],'tp-rec-education':anchors['tp-education'],'tp-rec-environment':[10,4,31],'tp-rec-culture':[-33,12,49],'tp-rec-sport':anchors['tp-sports'],'tp-rec-misc':anchors['tp-ai']};
function anchor(theme){return anchors[theme.id]||recordAnchors[theme.id]||anchors['tp-housing'];}
let pins=[];const cityPins=[];
function rebuildPins(){pins.forEach(p=>p.el.remove());pins=current().themes.filter(t=>!t.record).map((theme,i)=>{const el=node('button',undefined,'policy-pin');el.dataset.theme=theme.id;el.append(node('small',String(i+1).padStart(2,'0')),document.createTextNode(theme.name));el.setAttribute('aria-pressed','false');el.onclick=()=>showTheme(theme.id);$('#map-labels').append(el);return {theme,el};});}
for(const c of data.cities){const el=node('button',c.name,'city-pin');el.style.borderColor=palette[c.id].border;el.append(node('span','大台北生活圈'));el.onclick=()=>setCity(c.id);$('#map-labels').append(el);cityPins.push({city:c.id,el});}
function overlaps(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
function place(el,point,occupied,policy=false){const q=point.clone().project(camera);if(q.z>1||q.z< -1||Math.abs(q.x)>1.08||Math.abs(q.y)>1.05){el.hidden=true;return;}el.hidden=false;const w=el.offsetWidth,h=el.offsetHeight,x=(q.x*.5+.5)*innerWidth,y=(-q.y*.5+.5)*innerHeight;let chosen=null;for(const [dx,dy] of [[0,0],[0,-h-9],[0,h+9],[-w*.65,-h*.5],[w*.65,-h*.5],[0,-2*h-18]]){const box={x:x-w/2+dx,y:y-h+dy,w:w+8,h:h+8};if(box.x<7||box.x+w>innerWidth-7||box.y<8||box.y+h>innerHeight-65)continue;if(!occupied.some(o=>overlaps(box,o))){chosen=box;break;}}if(!chosen){el.hidden=true;return;}el.style.transform=`translate(${chosen.x}px,${chosen.y}px)`;occupied.push(chosen);}
function updatePins(){const occupied=[];for(const selector of ['.brand','.quick','#panel:not([hidden])','#guide:not([hidden])','#menu:not([hidden])']){const el=$(selector);if(el){const r=el.getBoundingClientRect();occupied.push({x:r.x-5,y:r.y-5,w:r.width+10,h:r.height+10});}}for(const p of cityPins){if(state.view!=='panorama'&&p.city===state.city){p.el.hidden=true;continue;}place(p.el,cities[p.city].toWorld([-4,8,19]),occupied);}for(const p of pins){p.el.hidden=state.view==='panorama';if(!p.el.hidden){p.el.setAttribute('aria-pressed',String(state.selected===p.theme.id));place(p.el,model().toWorld(anchor(p.theme)),occupied,true);}}}

function closeMenu(){$('#menu').hidden=true;$('#menu-button').setAttribute('aria-expanded','false');}
function closePanel(){$('#panel').hidden=true;state.selected=null;}
function panel(title,meta=current().name){closeMenu();$('#panel-title').textContent=title;$('#panel-meta').textContent=meta;$('#panel-body').replaceChildren();$('#panel').hidden=false;return $('#panel-body');}
function sourceLinks(ids,parent,city=current()){const byId=new Map(city.sources.map(s=>[s.id,s]));for(const id of [...new Set(ids||[])]){const s=byId.get(id);if(!s)continue;const a=node('a',s.publisher||s.title||'原始來源','source');a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';a.title=s.title||'';parent.append(a);}}
function showTheme(id,move=true){const theme=current().themes.find(t=>t.id===id);if(!theme)return;const body=panel(theme.name,`${current().name} · ${theme.record?'任內政績':'公開政見'} · ${theme.items.length} 項`);state.selected=id;body.append(node('span',theme.record?'政績紀錄':'政見主張','badge'));if(theme.summary)body.append(node('p',theme.summary));body.append(node('p',`資料查核：${current().checkedAt}。建築與地形皆為示意，不表示實際位置或政策已完成。`,'muted'));
 for(const item of theme.items){const article=node('article',undefined,'policy-item');article.dataset.item=item.id;article.append(node('h3',item.name));if(item.plain)article.append(node('p',item.plain));if(item.who)article.append(node('p','對象：'+item.who,'muted'));if(item.facts?.length){const ul=node('ul');item.facts.forEach(f=>ul.append(node('li',f)));article.append(ul);}if(item.phase)article.append(node('p','公開時程／狀態：'+(typeof item.phase==='string'?item.phase:JSON.stringify(item.phase)),'muted'));sourceLinks(item.sources,article);body.append(article);}
 const back=node('button','← 返回政策清單','back');back.onclick=showPolicies;body.append(back);if(move){state.view='policy';const p=anchor(theme),target=model().toWorld([p[0],Math.min(p[1]*.4,12),p[2]]),distance=Math.max(45,p[1]*2.3)*model().root.scale.x;focus(target.clone().add(new THREE.Vector3(1,.85,1.5).normalize().multiplyScalar(distance)),target);}}
function showPolicies(){const body=panel('政策清單',`${current().name} · ${current().candidate}`),input=node('input',undefined,'search');input.placeholder='搜尋政策、關鍵字';input.setAttribute('aria-label','搜尋政策');body.append(input);const results=node('div');body.append(results);const paint=()=>{results.replaceChildren();const query=input.value.trim().toLowerCase();for(const record of [false,true]){const themes=current().themes.filter(t=>t.record===record&&(!query||JSON.stringify(t).toLowerCase().includes(query)));if(!themes.length)continue;results.append(node('h2',record?'任內政績':'公開政見'));for(const theme of themes){const b=node('button',undefined,'list-row');b.dataset.theme=theme.id;b.append(node('span',theme.name),node('small',theme.items.length+' 項'));b.onclick=()=>showTheme(theme.id);results.append(b);}}if(!results.children.length)results.append(node('p','沒有符合的政策，試試其他關鍵字。','muted'));};paint();input.oninput=paint;
 if(current().connections.length){body.append(node('h2','大台北生活圈'));for(const c of current().connections){const item=node('article',undefined,'policy-item');item.append(node('p',c.text));sourceLinks(c.sources,item);body.append(item);}}
 body.append(node('p','本預覽呈現臺北市、新北市相關內容；部分跨區敘述未列出，引用連結保留供核對。','muted scope-note'));}
function showProgress(){const body=panel('政策進度');body.append(node('p','政見與政績分開呈現；未公開的時程不自行推估。'));for(const theme of current().themes){body.append(node('h2',theme.name));for(const item of theme.items){const row=node('article',undefined,'policy-item');row.append(node('h3',item.name),node('p',item.phase?(typeof item.phase==='string'?item.phase:JSON.stringify(item.phase)):(theme.record?'請依原始紀錄核對實施情形':'尚未公開明確時程'),'muted'));sourceLinks(item.sources,row);body.append(row);}}}
function showHelp(){const body=panel('使用說明','台北安可 · 大台北');for(const [title,text] of [['從臺北開始','進入後預設聚焦臺北市。上方可切換新北市，Home會回到臺北市預設視角；全景查看兩市。'],['轉動城市，探索不同面貌','電腦拖曳旋轉、滾輪縮放、右鍵平移；手機單指旋轉，雙指縮放與平移。建築可自然遮擋湖面，轉動後看見不同層次。'],['查閱政策與來源','點選地圖標牌或政策清單，查看內容、對象、公開時程及引用。政見與政績分開列出，實際政策以原始來源為準。'],['回到地圖','點選地圖空白處、右上角關閉或按Escape，即可關閉面板。'],['時間、導覽與音樂','工具選單提供白天、晚上、實際時間；實際時間依臺灣時區切換。按導覽時嘗試播放音樂，也可手動開關。全景停留5秒可慢速環繞，任何操作即停止。']]){body.append(node('h2',title),node('p',text));}body.append(node('p','本頁為大台北改版獨立預覽，尚未替換正式網站。地形、建築、橋梁與航線為概念配置，不作真實地理導航。','muted'),node('p','獨立整理，非任何候選人或政黨官方網站。','muted'),node('p','Designed by TPEncore © 2026 · Contact / TPEncore2026@gmail.com','muted'));}
function showLandmarks(){const body=panel('城市地標');for(const l of model().landmarks){const b=node('button',l.name,'list-row');b.onclick=()=>{const p=model().toWorld(l.point),target=model().toWorld([l.point[0],Math.min(l.point[1]*.5,20),l.point[2]]),distance=Math.max(50,l.point[1]*2.0)*model().root.scale.x;focus(target.clone().add(new THREE.Vector3(1,.85,1.4).normalize().multiplyScalar(distance)),target);closePanel();state.view='landmark';};body.append(b);}body.append(node('p','地標採縮尺意象，配置與外觀為概念示意。','muted'));}

const audio=new Audio('https://tpencore.tw/music/tpencoretheme.mp3');audio.loop=true;audio.preload='none';
function musicLabel(){$('#music-label').textContent='音樂・'+(state.music?'開啟':'關閉');}
async function playMusic(){try{await audio.play();state.music=true;musicLabel();}catch{state.music=false;musicLabel();status('音樂暫時無法播放，可稍後再試。');}}
function toggleMusic(){if(state.music){audio.pause();state.music=false;musicLabel();}else playMusic();}
function stopGuide(){state.guide=null;$('#guide').hidden=true;document.body.classList.remove('guide-open');}
function guideStep(){if(!state.guide)return;const themes=current().themes.filter(t=>!t.record),index=state.guide.index,theme=themes[index];showTheme(theme.id);closePanel();state.selected=theme.id;$('#guide').hidden=false;document.body.classList.add('guide-open');$('#guide-city').textContent=current().name+' · 城市導覽';$('#guide-count').textContent=`${index+1} / ${themes.length}`;$('#guide-title').textContent=theme.name;$('#guide-prev').disabled=index===0;$('#guide-next').textContent=index===themes.length-1?'完成導覽':'下一站 →';}
function startGuide(){closeMenu();state.guide={index:0};playMusic();guideStep();}
$('#guide-prev').onclick=()=>{if(state.guide?.index>0){state.guide.index--;guideStep();}};$('#guide-next').onclick=()=>{if(!state.guide)return;if(++state.guide.index>=current().themes.filter(t=>!t.record).length){stopGuide();cityView(state.city);}else guideStep();};$('#guide-stop').onclick=stopGuide;$('#guide-details').onclick=()=>{if(state.guide)showTheme(current().themes.filter(t=>!t.record)[state.guide.index].id,false);};

function setTime(mode){state.time=mode;$('#time-mode').value=mode;const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Taipei',hour:'2-digit',hour12:false}).format(new Date())),night=mode==='night'||mode==='real'&&(hour<6||hour>=18);state.night=night;sun.color.set(night?'#a8c3f1':'#fff0cc');sun.intensity=night?.48:3.3;hemi.intensity=night?.6:1.65;sky.material.uniforms.citySkyTint.value.set(night?'#102b51':'#80b8e4');sky.material.uniforms.cityCloudColor.value.set(night?'#344e73':'#fffaf0');sky.material.uniforms.sunPosition.value.set(night?-150:-150,night?-25:290,170);ocean.material.color.set(night?'#143a58':'#309eb8');scene.fog.color.set(night?'#173454':'#9ec9da');for(const city of Object.values(cities)){for(const glass of [city.glass,city.darkGlass]){glass.emissive.set('#ffdb9a');glass.emissiveIntensity=night?.3:0;}const lamp=city.art.mat('#f1e6b8');lamp.emissive.set('#ffe4ad');lamp.emissiveIntensity=night?1.2:0;}}
function setQuality(mode){$('#quality').value=mode;renderer.setPixelRatio(mode==='high'?Math.min(devicePixelRatio,2):1);ao.enabled=mode==='high';renderer.shadowMap.enabled=mode==='high';renderer.setSize(innerWidth,innerHeight);composer.setPixelRatio(renderer.getPixelRatio());composer.setSize(innerWidth,innerHeight);scene.traverse(o=>{if(o.material)o.material.needsUpdate=true;});}
$('#time-mode').onchange=e=>setTime(e.target.value);$('#quality').onchange=e=>setQuality(e.target.value);
setInterval(()=>{if(state.time==='real')setTime('real');},60000);
$('#menu-button').onclick=()=>{stopOrbit();const open=$('#menu').hidden;$('#menu').hidden=!open;$('#menu-button').setAttribute('aria-expanded',String(open));};$('#home').onclick=()=>home();$('#panorama').onclick=()=>panorama();$('#close-panel').onclick=closePanel;all('[data-city]').forEach(b=>b.onclick=()=>setCity(b.dataset.city));
const actions={policies:showPolicies,progress:showProgress,help:showHelp,panorama,guide:startGuide,landmarks:showLandmarks,music:toggleMusic,motion:()=>{state.motion=!state.motion;$('#motion').textContent='場景動態・'+(state.motion?'開啟':'關閉');$('#motion').setAttribute('aria-pressed',String(state.motion));}};
all('[data-action]').forEach(b=>b.onclick=()=>{stopOrbit();actions[b.dataset.action]();if(!['music','motion'].includes(b.dataset.action))closeMenu();});
renderer.domElement.addEventListener('pointerdown',()=>{closeMenu();closePanel();stopOrbit();});renderer.domElement.addEventListener('wheel',stopOrbit,{passive:true});
addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#menu').hidden)closeMenu();else if(!$('#panel').hidden)closePanel();else stopGuide();stopOrbit();}});
reduced.addEventListener('change',()=>{if(reduced.matches){stopOrbit();state.motion=false;$('#motion').textContent='場景動態・關閉';$('#motion').setAttribute('aria-pressed','false');}});
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);composer.setSize(innerWidth,innerHeight);});
function enter(){state.entered=true;$('#entry').hidden=true;home(true);showHelp();}
function render(){controls.update();camera.near=Math.max(.3,Math.min(20,camera.position.distanceTo(controls.target)/60));camera.updateProjectionMatrix();sky.position.copy(camera.position);renderer.info.reset();composer.render();updatePins();}
const clock=new THREE.Clock();function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.05);if(flight){const t=Math.min(1,(performance.now()-flight.time)/900),e=t*t*(3-2*t);camera.position.lerpVectors(flight.from,flight.to,e);controls.target.lerpVectors(flight.start,flight.end,e);if(t===1)flight=null;}if(state.motion){elapsed+=dt;Object.values(cities).forEach(c=>c.advance(elapsed));}render();}
home(true);setTime('day');render();$('#entry-title').textContent='一起打造你我的大台北';$('#entry-note').textContent='從臺北市出發，探索與新北連結的城市生活。';$('#enter').disabled=false;$('#enter').textContent='進入大台北';$('#enter').onclick=enter;
window.GREATER_TAIPEI={data,state,cities,scene,renderer,camera,controls,ao,enter,home,setCity,panorama,showTheme,showPolicies,showProgress,showHelp,showLandmarks,closePanel,setTime,setQuality,stopGuide,snapshot(draw=true){if(flight){camera.position.copy(flight.to);controls.target.copy(flight.end);flight=null;}if(draw)render();return {city:state.city,view:state.view,entered:state.entered,cityIds:Object.keys(cities),themes:current().themes.length,items:current().themes.reduce((n,t)=>n+t.items.length,0),night:state.night,time:state.time,calls:renderer.info.render.calls,triangles:renderer.info.render.triangles};}};
document.documentElement.dataset.ready='true';frame();
